import React, { useEffect, useState } from "react";

type Props = {
  open: boolean;
  onClose: () => void;
  onSubmit?: (data: { birthday: string; gender: "M" | "W" }) => void;
};

export default function OnboardingModal({ open, onClose, onSubmit }: Props) {
  const [birthday, setBirthday] = useState("");
  const [gender, setGender] = useState<"M" | "W" | null>(null);

  // ESC 닫기
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  const valid = birthday && gender;

  const handleSubmit = () => {
    if (!valid) return;
    onSubmit?.({ birthday, gender: gender! });
    onClose();
  };

  if (!open) return null;

  return (
    <div
      aria-modal
      role="dialog"
      className="fixed inset-0 z-50 flex items-center justify-center"
    >
      {/* Dim + 배경 흐림 */}
      <div
        className="absolute inset-0 bg-black/40 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* 카드 */}
      <div className="relative z-10 mx-4 w-full max-w-md rounded-3xl bg-white p-6 shadow-xl">
        <h2 className="text-2xl font-extrabold tracking-tight text-gray-900 text-center">
          LENDY, <span className="font-black">렌탈 구매 서비스</span>
        </h2>

        <p className="mt-3 text-center text-sm leading-6 text-gray-500">
          첫 Lendy의 방문을 환영합니다. <br />
          더 좋은 서비스를 제공하기 위해 필수정보를 입력해주세요 :)
        </p>

        {/* 생년월일 */}
        <label className="mt-6 block text-sm font-medium text-gray-700">
          생년월일
        </label>
        <div className="mt-2 flex items-center gap-3 rounded-xl border px-4 py-3">
          <input
            type="date"
            className="w-full outline-none"
            value={birthday}
            onChange={(e) => setBirthday(e.target.value)}
          />
          <span className="opacity-60">📅</span>
        </div>

        {/* 성별 */}
        <div className="mt-5 grid grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => setGender("M")}
            className={[
              "h-12 rounded-full border text-base font-semibold transition",
              gender === "M"
                ? "bg-gray-900 text-white border-gray-900"
                : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            ].join(" ")}
          >
            Men
          </button>
          <button
            type="button"
            onClick={() => setGender("W")}
            className={[
              "h-12 rounded-full border text-base font-semibold transition",
              gender === "W"
                ? "bg-emerald-300 text-white border-emerald-300"
                : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            ].join(" ")}
          >
            Women
          </button>
        </div>

        {/* 완료 버튼 */}
        <button
          type="button"
          disabled={!valid}
          onClick={handleSubmit}
          className="mt-7 h-12 w-full rounded-full bg-gray-400 text-white disabled:opacity-40 disabled:cursor-not-allowed"
        >
          완료
        </button>

        {/* 닫기 (선택) */}
        <button
          aria-label="close"
          onClick={onClose}
          className="absolute right-3 top-3 rounded-full p-2 text-gray-400 hover:bg-gray-100"
        >
          ✕
        </button>
      </div>
    </div>
  );
}
